_MAN = [("Paso. Ilayo kaagad ang biktima sa lugar ng kinapasuan.", "Burns. Move the victim away right away from the place where the burn occurred."), ("Alalayan ang katawan ng biktima.", "Support the victim’s body."), ("Huwag hawakan ang apektadong balat.", "Do not touch the affected skin."), ("Buhusan ng malamig na tubig ang paso sa loob ng sampung minuto.", "Pour cold water on the burn for ten minutes."), ("Pilay. Ipirmi at suportahan ang bahaging napilay.", "Sprain. Stabilize and support the sprained part."), ("Gawing komportable ang posisyon.", "Make the position comfortable."), ("Itaas ang paa o braso para mabawasan ang pagdaloy ng dugo.", "Raise the foot or arm to reduce the flow of blood."), ("Ipahinga ang napinsalang bahagi at ikonsulta sa doktor.", "Let the injured part rest and consult the doctor."), ("Pagkahimatay. Ihiga ang biktima.", "Fainting. Lay the victim down."), ("Dapat na mas mataas sa ulo ang mga paa at binti.", "The feet and legs should be higher than the head."), ("Luwagan ang damit upang makadaloy nang husto ang dugo sa katawan.", "Loosen the clothing so that blood can flow freely in the body."), ("Painumin ng tubig kapag nagkamalay.", "Give water to drink when the victim regains consciousness."), ("Kagat ng ahas. Pakalmahin ang biktima.", "Snake bite. Calm the victim."), ("Ilagay sa mababang posisyon ang bahagi ng katawan na nakagat upang bumagal ang pagdaloy ng dugo.", "Put the bitten part of the body in a low position so that the flow of blood slows down."), ("Sugat. Diinan ang sugat para huminto ang dugo.", "Wound. Press the wound to stop the blood."), ("Lapatan ng cold compress o malamig na basang tela ang sugat.", "Apply a cold compress or a cold wet cloth on the wound."), ("Takpan ang sugat ng gasa o benda upang maiwasan ang impeksyon.", "Cover the wound with gauze or bandage to avoid infection.")]
