        + [F("Buhusan ng ___ na tubig ang paso. (cold)", "malamig", ["maligamgam", "mainit"], "malamig."), F("___ ang sugat para huminto ang dugo. (press)", "Diinan", ["Takpan", "Buhusan"], "diinan."), F("___ ang biktima. (calm)", "Pakalmahin", ["Ihiga", "Itaas"], "pakalmahin."), F("Ihiga ang ___. (victim)", "biktima", ["paso", "benda"], "biktima."), F("Kumunsulta sa doktor, lalo na kung ___ ang sugat. (deep)", "malalim", ["maliit", "malinis"], "malalim.")]
