# ------------------------------------------------------------------ 4 grammar A an/han/nan
_EX = [("Tapalan ang sugat ng kuritas at gasa.", "Patch the wound with band aid and gauze."), ("Hawakan mo ang sugat ng pasyente.", "Touch the wound of the patient."), ("Hugasan itong mabuti at pahiran ng povidone iodine.", "Wash it well and apply povidone iodine."), ("Pahiran ng povidone iodine ang sugat.", "Apply povidone iodine on the wound."), ("Kailangan alagaan at bantayang mabuti at bigyan ng sapat na pagkain ang maysakit.", "You need to take care of, monitor, and give the sick person enough food."), ("Diinan ang sugat para huminto ang dugo.", "Put pressure on the wound to stop the bleeding."), ("Luwagan ang damit upang makadaloy nang husto ang dugo sa katawan.", "Loosen the clothing to enable the blood to flow freely."), ("Dalhan mo ng benda o gasa si Raul.", "Bring bandage or gauze to Raul. Or: Bring Raul bandage or gauze.")]
